import org.junit.Assert;

public class TestAssertions {
    private int count = 0;
    private Object buffer = new Object();
    private Object fileBuffer = new Object();

    public void setUp() {
        count = 1;
        fileBuffer = buffer; // Assign for test
    }

    @org.junit.Test
    public void testCountsAndBuffers() {
        // Primitive equality check
        Assert.assertEquals(count, 1);

        // Reference equality check
        Assert.assertSame(buffer, fileBuffer);

        // Another primitive check with different order
        Assert.assertEquals(1, count);

        // Boxed primitive equality check
        Integer num1 = 10;
        Integer num2 = 10;
        Assert.assertSame(num1, num2); // Object comparison for boxed types
    }
}

