import org.junit.Assert;

public class TestAssertions {
    private int count = 0;
    private Object buffer = new Object();

    @org.junit.Test
    public void testOtherAssertions() {
        // Not '==' operator
        Assert.assertTrue(count > 0);
        Assert.assertTrue(buffer instanceof Object);
        Assert.assertTrue(true);

        // Other Assert methods
        Assert.assertFalse(count == 1);
        Assert.assertNull(buffer);

        // Not an Assert.assertTrue call
        boolean result = (count == 1);
    }
}
